from pydantic import BaseModel, Field

class ProvidedPaper(BaseModel):
    """A single paper from the collection, identified by its title and its citations to other collection papers."""
    title: str | None = Field(description="The title of the paper")
    cites_provided_papers: list[str] = Field(
        description="Titles of the OTHER provided papers that are referenced in this paper's bibliography"
    )

class Parse(BaseModel):
    papers: list[ProvidedPaper]
